import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  Divider,
  List,
  ListItemButton,
  ListItemText,
  Paper,
  Container,
  useMediaQuery,
  useTheme,
} from "@mui/material";

const lectures = [
  {
    title: "Googleスプレッドシート講座",
    date: "10月19日（日）",
    time: "10:00〜11:30/14:00〜15:30",
    desc: "Excelの代替として注目のGoogleスプレッドシートを学ぶ講座です。",
    formUrl:
      "https://docs.google.com/forms/d/e/1FAIpQLSf178o_T6mZ7_yOFR20J4d3bHGts89XRKdJcPICv-KCRsqhmA/viewform?usp=header",
  },
  {
    title: "自動化デジタル活用講座",
    date: "11月16日（日）",
    time: "10:00〜11:30/14:00〜15:30",
    desc: "業務効率化のための自動化ツールを実践的に学びます。",
    formUrl:
      "https://docs.google.com/forms/d/e/1FAIpQLSf178o_T6mZ7_yOFR20J4d3bHGts89XRKdJcPICv-KCRsqhmA/viewform?usp=header",
  },
  {
    title: "Webデザイン講座",
    date: "12月21日（日）",
    time: "10:00〜11:30/14:00〜15:30",
    desc: "無料ツールを活用したWebデザインを体験的に学べます。",
    formUrl:
      "https://docs.google.com/forms/d/e/1FAIpQLSf178o_T6mZ7_yOFR20J4d3bHGts89XRKdJcPICv-KCRsqhmA/viewform?usp=header",
  },
];

export default function LectureReservation() {
  const [selectedLecture, setSelectedLecture] = useState(lectures[0]);
  const [open, setOpen] = useState(false);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  useEffect(() => {
    const section = document.getElementById("reservation");
    if (!section) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
        }
      },
      { threshold: 0.1 }
    );
    observer.observe(section);
    return () => observer.disconnect();
  }, []);

  return (
    <>
      <Container maxWidth="lg">
        <Box textAlign="center" mb={6}>
          <Typography variant="body1">
            各講座は事前予約制です。左のリストから講座を選ぶと、右側に詳細が表示されます。
          </Typography>
        </Box>

        <Box display="flex" justifyContent="center">
          <Box
            display="flex"
            flexDirection={isMobile ? "column" : "row"}
            sx={{ maxWidth: "1000px", width: "100%" }}
          >
            <Box
              sx={{
                width: isMobile ? "100%" : 300,
                flexShrink: 0,
                position: isMobile ? "relative" : "sticky",
                top: isMobile ? "auto" : 100,
                alignSelf: isMobile ? "auto" : "flex-start",
                mb: isMobile ? 2 : 0,
              }}
            >
              <Paper elevation={2} sx={{ boxSizing: "border-box" }}>
                <List component="nav">
                  {lectures.map((lecture, index) => (
                    <ListItemButton
                      key={index}
                      selected={selectedLecture?.title === lecture.title}
                      onClick={() => setSelectedLecture(lecture)}
                    >
                      <ListItemText
                        primary={lecture.title}
                        secondary={lecture.date}
                      />
                    </ListItemButton>
                  ))}
                </List>
              </Paper>
            </Box>

            <Box sx={{ flexGrow: 1, ml: isMobile ? 0 : 4 }}>
              <Paper
                elevation={3}
                sx={{
                  p: 4,
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  boxSizing: "border-box",
                }}
              >
                <Box textAlign="center">
                  <Typography
                    variant="h5"
                    gutterBottom
                    sx={{ fontWeight: 600 }}
                  >
                    {selectedLecture?.title}
                  </Typography>
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{ mb: 1 }}
                  >
                    {selectedLecture?.date} : {selectedLecture?.time}
                  </Typography>
                  <Typography variant="body1" sx={{ mb: 3 }}>
                    {selectedLecture?.desc}
                  </Typography>
                  <Button variant="contained" onClick={handleOpen}>
                    予約する
                  </Button>
                </Box>
              </Paper>
            </Box>
          </Box>
        </Box>

        <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
          <DialogTitle>{selectedLecture?.title}の予約フォーム</DialogTitle>
          <DialogContent dividers>
            <iframe
              src={selectedLecture?.formUrl}
              width="100%"
              height="500"
              style={{ border: "none" }}
              title="予約フォーム"
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={handleClose}>閉じる</Button>
          </DialogActions>
        </Dialog>
      </Container>
    </>
  );
}
