import React from "react";
import { Box, Divider } from "@mui/material";

const DividerBox = () => {
  return (
    <Box textAlign="center" mb={6}>
      <Divider
        sx={{
          width: 60,
          mx: "auto",
          mb: 2,
          borderBottomWidth: 3,
          borderColor: "primary.main",
        }}
      />
    </Box>
  );
};

export default DividerBox;
