import React from "react";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import "./MyCalendar.css";

const calendars = [
  { date: new Date(2025, 9, 1), highlightDates: [new Date(2025, 9, 19)] }, // 10月
  { date: new Date(2025, 10, 1), highlightDates: [new Date(2025, 10, 16)] }, // 11月
  { date: new Date(2025, 11, 1), highlightDates: [new Date(2025, 11, 21)] }, // 12月
];

function isSameDay(date1, date2) {
  return (
    date1.getFullYear() === date2.getFullYear() &&
    date1.getMonth() === date2.getMonth() &&
    date1.getDate() === date2.getDate()
  );
}

function MyCalendar({ activeStartDate, highlightDates }) {
  return (
    <Calendar
      defaultActiveStartDate={activeStartDate}
      value={null} // ← 選択状態を解除
      tileClassName={({ date, view }) =>
        view === "month" && highlightDates.some((d) => isSameDay(d, date))
          ? "cal-highlight"
          : null
      }
    />
  );
}

export default function ThreeCalendars() {
  return (
    <div className="calendar-container">
      {calendars.map(({ date, highlightDates }, index) => (
        <MyCalendar
          key={index}
          activeStartDate={date}
          highlightDates={highlightDates}
        />
      ))}
    </div>
  );
}
